{"cwe": "CWE-327", "severity": "WARNING", "verdict": "Confirm", "explanation": "Even though the function name is not test_-prefixed, this is a live authentication path hashing passwords with MD5; a fixed username string is not a random per-user salt. Real production finding -> Confirm.", "patch": "def _pw_digest(raw, salt):
    import hashlib
    return hashlib.scrypt(raw.encode(), salt=salt, n=2**14, r=8, p=1)

def register(user, raw):
    import secrets
    salt = secrets.token_bytes(16)
    store(user, salt.hex(), _pw_digest(raw, salt).hex())

def verify_login(user, raw):
    salt, stored = load(user)
    return compare(_pw_digest(raw, bytes.fromhex(salt)).hex(), stored)"}

{"cwe": "CWE-327", "severity": "WARNING", "verdict": "Confirm", "explanation": "Encrypting sensitive data with DES: 56-bit key and 64-bit block are cryptographically weak. Real finding -> Confirm.", "patch": "from Crypto.Cipher import AES
