{"cwe": "CWE-327", "severity": "WARNING", "verdict": "Confirm", "explanation": "An async web login handler (production route, not a test) compares passwords through MD5. MD5 password verification is insecure; must use a salted KDF. Real finding -> Confirm.", "patch": "import hashlib, hmac
async def handle_login(request):
    body = await request.json()
    stored = DB.get_user(body["user"])           # {salt, hash}
    digest = hashlib.scrypt(body["password"].encode(), salt=stored["salt"], n=2**14, r=8, p=1)
    return {"ok": hmac.compare_digest(digest, stored["hash"])}"}

